// ========= AtomicRecordArraySetValue / AtomicRecordArrayGetValue =========

// Verifies that setting and getting each of the five Value types at position 0
// works correctly.
TEST(ArrayDbAtomicRecordArrayTest, SetAndGetValueAllValues) {
    const Value kAllValues[] = {kUndecided, kLose, kDraw, kTie, kWin};

    for (Value val : kAllValues) {
        AtomicRecordArray *array = AtomicRecordArrayCreate(4);
        ASSERT_NE(array, nullptr);

        AtomicRecordArraySetValue(array, 0, val);

        EXPECT_EQ(AtomicRecordArrayGetValue(array, 0), val)
            << "Value should round-trip for Value " << val << ".";

        AtomicRecordArrayDestroy(array);
    }
}

// Verifies that SetValue does not corrupt the remoteness field.
TEST(ArrayDbAtomicRecordArrayTest, SetValuePreservesRemoteness) {
    AtomicRecordArray *array = AtomicRecordArrayCreate(4);
    ASSERT_NE(array, nullptr);

    AtomicRecordArraySetValueRemoteness(array, 0, kLose, 42);
    AtomicRecordArraySetValue(array, 0, kWin);

    EXPECT_EQ(AtomicRecordArrayGetValue(array, 0), kWin)
        << "Value should be updated to kWin.";
    EXPECT_EQ(AtomicRecordArrayGetRemoteness(array, 0), 42)
        << "Remoteness should remain 42 after changing only the value.";

    AtomicRecordArrayDestroy(array);
}

