// Verifies that serializing one record at a time produces correct chunks.
TEST(ArrayDbAtomicRecordArrayTest, SerializeStreamingOneRecordAtATime) {
    constexpr int64_t kSize = 4;
    AtomicRecordArray *array = AtomicRecordArrayCreate(kSize);
    ASSERT_NE(array, nullptr);

    const Value kValues[] = {kWin, kLose, kTie, kDraw};
    const int kRemotenesses[] = {10, 20, 30, 40};
    for (int64_t i = 0; i < kSize; ++i) {
        AtomicRecordArraySetValueRemoteness(array, i, kValues[i],
                                            kRemotenesses[i]);
    }

    size_t chunk = sizeof(Record);
    size_t offset = 0;
    for (int64_t i = 0; i < kSize; ++i) {
        Record rec;
        size_t written =
            AtomicRecordArraySerializeStreaming(array, offset, &rec, chunk);
        EXPECT_EQ(written, chunk)
            << "Each single-record call should return sizeof(Record).";
        EXPECT_EQ(RecordGetValue(&rec), kValues[i])
            << "Value mismatch for chunk " << i << ".";
        EXPECT_EQ(RecordGetRemoteness(&rec), kRemotenesses[i])
            << "Remoteness mismatch for chunk " << i << ".";
        offset += written;
    }

    // Next call should indicate no data remains.
    Record dummy;
    size_t written =
        AtomicRecordArraySerializeStreaming(array, offset, &dummy, chunk);
    EXPECT_EQ(written, static_cast<size_t>(0))
        << "Should return 0 when no data remains.";

    AtomicRecordArrayDestroy(array);
}

// Verifies that chunked serialization in two equal halves is correct.
TEST(ArrayDbAtomicRecordArrayTest, SerializeStreamingTwoChunks) {
    constexpr int64_t kSize = 6;
    AtomicRecordArray *array = AtomicRecordArrayCreate(kSize);
    ASSERT_NE(array, nullptr);

    for (int64_t i = 0; i < kSize; ++i) {
        AtomicRecordArraySetValueRemoteness(array, i, kWin,
                                            static_cast<int>(i));
    }

    // Serialize in one shot for reference.
    size_t total = AtomicRecordArrayGetSerializedSize(array);
    std::vector<Record> full_buf(kSize);
    AtomicRecordArraySerializeStreaming(array, 0, full_buf.data(), total);

    // Serialize in two halves.
    constexpr int64_t kHalf = kSize / 2;
    size_t chunk_bytes = kHalf * sizeof(Record);
    std::vector<Record> chunk1(kHalf), chunk2(kHalf);

    size_t w1 = AtomicRecordArraySerializeStreaming(array, 0, chunk1.data(),
                                                    chunk_bytes);
    size_t w2 = AtomicRecordArraySerializeStreaming(array, w1, chunk2.data(),
                                                    chunk_bytes);

    EXPECT_EQ(w1, chunk_bytes)
        << "First half should be " << chunk_bytes << " bytes.";
    EXPECT_EQ(w2, chunk_bytes)
        << "Second half should be " << chunk_bytes << " bytes.";
    EXPECT_EQ(std::memcmp(chunk1.data(), full_buf.data(), chunk_bytes), 0)
        << "First chunk should match the first half of the full serialization.";
    EXPECT_EQ(std::memcmp(chunk2.data(), full_buf.data() + kHalf, chunk_bytes),
              0)
        << "Second chunk should match the second half of the full "
           "serialization.";

    AtomicRecordArrayDestroy(array);
}

// Verifies uneven chunking (buffer fits fewer records than remain).
TEST(ArrayDbAtomicRecordArrayTest, SerializeStreamingUnevenChunks) {
    constexpr int64_t kSize = 5;
    AtomicRecordArray *array = AtomicRecordArrayCreate(kSize);
    ASSERT_NE(array, nullptr);

    for (int64_t i = 0; i < kSize; ++i) {
        AtomicRecordArraySetValueRemoteness(array, i, kLose,
                                            static_cast<int>(i * 10));
    }

    // Buffer holds 3 records; expect: 3, then 2, then 0.
    std::vector<Record> buf(3);
    size_t chunk_bytes = 3 * sizeof(Record);

    size_t w1 =
        AtomicRecordArraySerializeStreaming(array, 0, buf.data(), chunk_bytes);
    EXPECT_EQ(w1, 3 * sizeof(Record))
        << "First call should serialize 3 records.";

    size_t w2 =
        AtomicRecordArraySerializeStreaming(array, w1, buf.data(), chunk_bytes);
    EXPECT_EQ(w2, 2 * sizeof(Record))
        << "Second call should serialize 2 records.";

    size_t w3 = AtomicRecordArraySerializeStreaming(array, w1 + w2, buf.data(),
                                                    chunk_bytes);
    EXPECT_EQ(w3, static_cast<size_t>(0))
        << "Third call should return 0 (no data remaining).";

    AtomicRecordArrayDestroy(array);
}

