// Verifies byte-identical output between a single full serialization and
// concatenated 2-record chunks.
TEST(ArrayDbAtomicRecordArrayTest,
     SerializeStreamingChunkedContentMatchesFull) {
    constexpr int64_t kSize = 10;
    AtomicRecordArray *array = AtomicRecordArrayCreate(kSize);
    ASSERT_NE(array, nullptr);

    for (int64_t i = 0; i < kSize; ++i) {
        AtomicRecordArraySetValueRemoteness(array, i, kWin,
                                            static_cast<int>(i * 7));
    }

    // Full serialization in one call.
    size_t total = AtomicRecordArrayGetSerializedSize(array);
    std::vector<uint8_t> full_buf(total);
    AtomicRecordArraySerializeStreaming(array, 0, full_buf.data(), total);

    // Chunked serialization (2 records per chunk).
    size_t chunk_bytes = 2 * sizeof(Record);
    std::vector<uint8_t> chunked_buf(total);
    size_t offset = 0;
    while (offset < total) {
        size_t written = AtomicRecordArraySerializeStreaming(
            array, offset, chunked_buf.data() + offset, chunk_bytes);
        ASSERT_GT(written, static_cast<size_t>(0))
            << "Chunked serialization stalled at offset " << offset << ".";
        offset += written;
    }

    EXPECT_EQ(std::memcmp(full_buf.data(), chunked_buf.data(), total), 0)
        << "Concatenated chunked output should be byte-identical to the full "
           "serialization.";

    AtomicRecordArrayDestroy(array);
}

