// Verifies that serialization after mixed operations produces correct output.
TEST(ArrayDbAtomicRecordArrayTest, SerializeAfterMixedOperations) {
    constexpr int64_t kSize = 5;
    AtomicRecordArray *array = AtomicRecordArrayCreate(kSize);
    ASSERT_NE(array, nullptr);

    AtomicRecordArraySetValueRemoteness(array, 0, kLose, 1);
    AtomicRecordArraySetValue(array, 0, kWin);  // now (kWin, 1)

    AtomicRecordArraySetValueRemoteness(array, 1, kUndecided, 10);
    AtomicRecordArrayDecrementNumUndecidedChildren(array, 1);  // count -> 9

    AtomicRecordArraySetValueRemoteness(array, 2, kLose, 0);
    AtomicRecordArrayMaximize(array, 2, kTie, 50,
                              CompareByValueThenRemoteness);  // -> (kTie, 50)

    AtomicRecordArraySetValueRemoteness(array, 3, kDraw, kRemotenessMax);
    AtomicRecordArraySetRemoteness(array, 3, 5);  // -> (kDraw, 5)

    AtomicRecordArraySetValueRemoteness(array, 4, kUndecided, 3);
    AtomicRecordArrayClearNumUndecidedChildren(array, 4);  // count -> 0

    size_t total = AtomicRecordArrayGetSerializedSize(array);
    std::vector<Record> buf(kSize);
    AtomicRecordArraySerializeStreaming(array, 0, buf.data(), total);

    // Verify each serialized record matches what the getters report.
    for (int64_t i = 0; i < kSize; ++i) {
        EXPECT_EQ(RecordGetValue(&buf[i]), AtomicRecordArrayGetValue(array, i))
            << "Serialized value at position " << i
            << " does not match getter.";
        EXPECT_EQ(RecordGetRemoteness(&buf[i]),
                  AtomicRecordArrayGetRemoteness(array, i))
            << "Serialized remoteness at position " << i
            << " does not match getter.";
    }

    AtomicRecordArrayDestroy(array);
}

// ============================ Multithreaded Tests ============================

// Verifies that concurrent SetValue calls do not corrupt the remoteness field.
TEST(ArrayDbAtomicRecordArrayTest, ConcurrentSetValuePreservesRemoteness) {
    AtomicRecordArray *array = AtomicRecordArrayCreate(1);
    ASSERT_NE(array, nullptr);

    AtomicRecordArraySetValueRemoteness(array, 0, kLose, 42);

    std::vector<std::thread> threads;
    for (int t = 0; t < kNumThreads; ++t) {
        threads.emplace_back([array, t]() {
            for (int i = 0; i < kIterationsPerThread; ++i) {
                Value val =
                    (((t * kIterationsPerThread) + i) % 2 == 0) ? kWin : kLose;
                AtomicRecordArraySetValue(array, 0, val);
            }
        });
    }
    for (auto &th : threads) th.join();

    EXPECT_EQ(AtomicRecordArrayGetRemoteness(array, 0), 42)
        << "Remoteness should still be 42 after concurrent SetValue calls.";
    Value final_val = AtomicRecordArrayGetValue(array, 0);
    EXPECT_TRUE(final_val == kWin || final_val == kLose)
        << "Final value should be one of {kWin, kLose}.";

    AtomicRecordArrayDestroy(array);
}

// Verifies that concurrent SetRemoteness calls do not corrupt the value field.
TEST(ArrayDbAtomicRecordArrayTest, ConcurrentSetRemotenessPreservesValue) {
    AtomicRecordArray *array = AtomicRecordArrayCreate(1);
    ASSERT_NE(array, nullptr);

    AtomicRecordArraySetValueRemoteness(array, 0, kTie, 0);

    std::vector<std::thread> threads;
    for (int t = 0; t < kNumThreads; ++t) {
        threads.emplace_back([array, t]() {
            for (int i = 0; i < kIterationsPerThread; ++i) {
                int rmt =
                    ((t * kIterationsPerThread) + i) % (kRemotenessMax + 1);
                AtomicRecordArraySetRemoteness(array, 0, rmt);
            }
        });
    }
    for (auto &th : threads) th.join();

    EXPECT_EQ(AtomicRecordArrayGetValue(array, 0), kTie)
        << "Value should still be kTie after concurrent SetRemoteness calls.";
    int final_rmt = AtomicRecordArrayGetRemoteness(array, 0);
    EXPECT_GE(final_rmt, 0) << "Final remoteness should be non-negative.";
    EXPECT_LE(final_rmt, kRemotenessMax)
        << "Final remoteness should be at most kRemotenessMax.";

    AtomicRecordArrayDestroy(array);
}

// Verifies that concurrent decrements return values whose sum equals the
// triangular number of the initial count.
TEST(ArrayDbAtomicRecordArrayTest, ConcurrentDecrementTotalIsCorrect) {
    constexpr int kInitialCount = 1000;
    AtomicRecordArray *array = AtomicRecordArrayCreate(1);
    ASSERT_NE(array, nullptr);

    AtomicRecordArraySetValueRemoteness(array, 0, kUndecided, kInitialCount);

    std::vector<std::thread> threads;
    std::vector<long long> partial_sums(kNumThreads, 0);
    for (int t = 0; t < kNumThreads; ++t) {
        threads.emplace_back([array, &partial_sums, t]() {
            long long sum = 0;
            for (int i = 0; i < kIterationsPerThread; ++i) {
                sum += AtomicRecordArrayDecrementNumUndecidedChildren(array, 0);
            }
            partial_sums[t] = sum;
        });
    }
    for (auto &th : threads) th.join();

    long long total_sum = 0;
    for (int t = 0; t < kNumThreads; ++t) {
        total_sum += partial_sums[t];
    }

    // The sum of all returned old counts must equal the triangular number:
    // kInitialCount + (kInitialCount-1) + ... + 1.
    long long expected =
        static_cast<long long>(kInitialCount) * (kInitialCount + 1) / 2;
    EXPECT_EQ(total_sum, expected)
        << "Sum of returned values should equal the triangular number of the "
           "initial count.";
    EXPECT_EQ(AtomicRecordArrayGetNumUndecidedChildren(array, 0), 0)
        << "Final count should be 0.";

    AtomicRecordArrayDestroy(array);
}

// Verifies that concurrent clears result in exactly one nonzero return value.
TEST(ArrayDbAtomicRecordArrayTest, ConcurrentClearReturnsSingleNonzero) {
    constexpr int kInitialCount = 100;
    AtomicRecordArray *array = AtomicRecordArrayCreate(1);
    ASSERT_NE(array, nullptr);

    AtomicRecordArraySetValueRemoteness(array, 0, kUndecided, kInitialCount);

    std::vector<std::thread> threads;
    std::vector<int> nonzero_counts(kNumThreads, 0);
    std::vector<int> nonzero_values(kNumThreads, 0);
    for (int t = 0; t < kNumThreads; ++t) {
        threads.emplace_back([array, &nonzero_counts, &nonzero_values, t]() {
            for (int i = 0; i < kIterationsPerThread; ++i) {
                int result =
                    AtomicRecordArrayClearNumUndecidedChildren(array, 0);
                if (result != 0) {
                    nonzero_counts[t]++;
                    nonzero_values[t] = result;
                }
            }
        });
    }
    for (auto &th : threads) th.join();

    int total_nonzero = 0;
    int observed_value = 0;
    for (int t = 0; t < kNumThreads; ++t) {
        total_nonzero += nonzero_counts[t];
        if (nonzero_counts[t] > 0) {
            observed_value = nonzero_values[t];
        }
    }

    EXPECT_EQ(AtomicRecordArrayGetNumUndecidedChildren(array, 0), 0)
        << "Final count should be 0.";
    EXPECT_EQ(total_nonzero, 1)
        << "Exactly one clear call should have returned a nonzero value.";
    EXPECT_EQ(observed_value, kInitialCount)
        << "The nonzero return value should be the initial count.";

    AtomicRecordArrayDestroy(array);
}

// Verifies that concurrent Maximize calls converge to the maximum candidate.
TEST(ArrayDbAtomicRecordArrayTest, ConcurrentMaximizeConvergesToMax) {
    AtomicRecordArray *array = AtomicRecordArrayCreate(1);
    ASSERT_NE(array, nullptr);

    AtomicRecordArraySetValueRemoteness(array, 0, kUndecided, 0);

    // Each thread will offer candidates for a subset of value-remoteness pairs.
    // The maximum candidate under CompareByValueThenRemoteness is
    // (kWin, kRemotenessMax).
    std::vector<std::thread> threads;
    for (int t = 0; t < kNumThreads; ++t) {
        threads.emplace_back([array, t]() {
            const Value kValues[] = {kLose, kDraw, kTie, kWin};
            for (int i = 0; i < kIterationsPerThread; ++i) {
                int global_i = t * kIterationsPerThread + i;
                Value val = kValues[global_i % 4];
                int rmt = global_i % (kRemotenessMax + 1);
                AtomicRecordArrayMaximize(array, 0, val, rmt,
                                          CompareByValueThenRemoteness);
            }
        });
    }
    for (auto &th : threads) th.join();

    EXPECT_EQ(AtomicRecordArrayGetValue(array, 0), kWin)
        << "Final value should be kWin (the greatest Value offered).";
    EXPECT_GT(AtomicRecordArrayGetRemoteness(array, 0), 0)
        << "Final remoteness should be positive (many kWin candidates were "
           "offered).";

    AtomicRecordArrayDestroy(array);
}

// Verifies that concurrent SetValueRemoteness always produces a consistent
// record (no torn writes).
TEST(ArrayDbAtomicRecordArrayTest, ConcurrentSetValueRemoteness) {
    AtomicRecordArray *array = AtomicRecordArrayCreate(1);
    ASSERT_NE(array, nullptr);

    AtomicRecordArraySetValueRemoteness(array, 0, kLose, 0);

    // Each thread writes a recognizable pattern: thread t writes
    // (kValues[t], t * 100 + i % 100).
    const Value kValues[] = {kLose, kDraw, kTie, kWin};

    std::vector<std::thread> threads;
    for (int t = 0; t < kNumThreads; ++t) {
        threads.emplace_back([array, &kValues, t]() {
            for (int i = 0; i < kIterationsPerThread; ++i) {
                int rmt = t * 100 + (i % 100);
                AtomicRecordArraySetValueRemoteness(array, 0, kValues[t], rmt);
            }
        });
    }
    for (auto &th : threads) th.join();

    // The final state must match a (value, remoteness) pair written by some
    // thread, not a torn mix.
    Value final_val = AtomicRecordArrayGetValue(array, 0);
    int final_rmt = AtomicRecordArrayGetRemoteness(array, 0);

    bool found_match = false;
    for (int t = 0; t < kNumThreads; ++t) {
        if (final_val == kValues[t] && final_rmt >= t * 100 &&
            final_rmt < t * 100 + 100) {
            found_match = true;
            break;
        }
    }
    EXPECT_TRUE(found_match)
        << "Final record (value=" << final_val << ", remoteness=" << final_rmt
        << ") should match a (value, remoteness) pair written by one of the "
           "threads.";

    AtomicRecordArrayDestroy(array);
}

// Verifies that concurrent operations on different positions do not interfere.
TEST(ArrayDbAtomicRecordArrayTest, ConcurrentOperationsOnDifferentPositions) {
    // Each thread t operates exclusively on position t.
    AtomicRecordArray *array = AtomicRecordArrayCreate(kNumThreads);
    ASSERT_NE(array, nullptr);

    // Initialize all positions to (kUndecided, kIterationsPerThread).
    for (int t = 0; t < kNumThreads; ++t) {
        AtomicRecordArraySetValueRemoteness(array, t, kUndecided,
                                            kIterationsPerThread);
    }

    // Each thread decrements its own position kIterationsPerThread times,
    // draining it to 0.
    std::vector<std::thread> threads;
    for (int t = 0; t < kNumThreads; ++t) {
        threads.emplace_back([array, t]() {
            for (int i = 0; i < kIterationsPerThread; ++i) {
                AtomicRecordArrayDecrementNumUndecidedChildren(array, t);
            }
        });
    }
    for (auto &th : threads) th.join();

    // Every position should now have a count of 0, and value must remain
    // kUndecided (decrement is a no-op after the count reaches 0).
    for (int t = 0; t < kNumThreads; ++t) {
        EXPECT_EQ(AtomicRecordArrayGetValue(array, t), kUndecided)
            << "Position " << t << " value should remain kUndecided.";
        EXPECT_EQ(AtomicRecordArrayGetNumUndecidedChildren(array, t), 0)
            << "Position " << t << " count should be 0.";
    }

    AtomicRecordArrayDestroy(array);
}
